#include <iostream>
#include <string>
#include <vector>
class MyString {
public:
  MyString(const std::string& str) : data(str) { std::cout << "Copy constructor called\n"; }
  MyString(std::string&& str) : data(std::move(str)) { std::cout << "Move constructor called\n"; }
  MyString& operator=(const std::string& str) { data = str; std::cout << "Copy assignment called\n"; return *this; }
  MyString& operator=(std::string&& str) { data = std::move(str); std::cout << "Move assignment called\n"; return *this; }
  ~MyString() { std::cout << "Destructor called\n"; }
private:
  std::string data;
};
int main() {
  MyString s1 = "hello";
  MyString s2 = std::move(s1); // Move s1's resources to s2
  MyString s3; 
  s3 = std::move(s2); //Move assignment
  std::vector<MyString> vec;
  vec.emplace_back("emplace_back"); //Uses move constructor implicitly.
  return 0;
}
